```text
#include <iostream>
#include <vector>

int main() {
    // 创建一个空的整数 vector
    std::vector<int> nums;

    // 从尾部添加元素
    nums.push_back(10);
    nums.push_back(20);
    nums.push_back(30);

    // 查看元素个数和访问
    std::cout << "vector 大小: " << nums.size() << std::endl;
    std::cout << "第一个元素: " << nums[0] << std::endl;
    std::cout << "第二个元素: " << nums.at(1) << std::endl; // at 会检查越界

    // 用范围 for 循环遍历
    std::cout << "全部元素: ";
    for (int x : nums) {
        std::cout << x << " ";
    }
    std::cout << std::endl;

    // 删除最后一个元素
    nums.pop_back();
    std::cout << "pop 后大小: " << nums.size() << std::endl;

    return 0;
}

```
